{
  "pains": [
    {
      "id": "pain:stale-contact-data",
      "statement": "Half the list is people who already left or emails that bounce, so I end up cross-checking every row by hand before I dare send.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Contacts from the database tool are wrong, stale or bounce on the first send.",
        "operational": "Reps and agencies re-verify rows by hand, bounce rates rise and sending domains get burned. Deals in the CRM get worked against people who are gone.",
        "personal": "The rep or founder looks careless in front of prospects, and an agency owner has to explain to the client why the campaign produced nothing.",
        "personal_note": "The personal cost is inferred from the cross-checking complaint and the Validity revenue-loss figure. No source in the sweep states the embarrassment in the first person."
      },
      "workflow": "List pull in Apollo or ZoomInfo, export to a CSV or Clay table, then before loading into Smartlead, Instantly or Outreach the rep cross-checks emails and titles on LinkedIn by hand.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "paying",
        "what": "Buyers keep paying for database seats and credits and still report having to cross-check the data. 37% of CRM users say poor data quality cost them revenue.",
        "cites": ["src:19", "src:15"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A first campaign to a fresh export bounces or gets no replies, and the founder blames the tool or the channel.", "cites": ["src:19"]},
        {"event": "A CRM audit finds most records are incomplete or out of date.", "cites": ["src:15"]}
      ],
      "who_feels": ["end_user", "economic_buyer"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "can mistake in data so we have cross check data", "cites": ["src:19"]},
            {"situation": "when_comparing", "verbatim": "The information seems to be mostly there, I just need to checkout the accuracy.", "cites": ["src:19"]}
          ],
          "costs_them": "Hours of manual checking before every send, plus replies lost to bounced or wrong contacts.",
          "fears": "Burning the sending domain and looking sloppy to a prospect who left the company months ago.",
          "dream_outcome": "Loading a list straight into the sequencer, trusting it without spot-checking."
        },
        "economic_buyer": {
          "says": [
            {"situation": "to_their_boss", "verbatim": "76% said less than half of their organization's CRM data is accurate and complete.", "cites": ["src:15"]}
          ],
          "costs_them": "Revenue lost to deals worked against bad records, and seats paid for data that has to be redone.",
          "fears": "Funding a pipeline motion that runs on data nobody trusts.",
          "dream_outcome": "A CRM the reps believe, so pipeline numbers mean something."
        }
      },
      "relief": {
        "line": "Lists that land. The export goes into the sequencer without a manual check, and bounces stop being the story.",
        "says": [],
        "gap": "Review sites and practitioner communities showed complaints about bad data but no buyer describing the after state in their own words. Reddit and G2 were blocked."
      },
      "euphoria": {
        "line": "Data you stop thinking about. A year later nobody on the team checks contacts by hand, and the CRM is the source people quote.",
        "says": [],
        "gap": "No buyer voice found describing the lasting state. Review-site praise is about power and flexibility, not accuracy."
      },
      "segments": ["seg:lean", "seg:agency", "seg:revops"],
      "feature_ref": "feat:waterfall",
      "cites": ["src:19", "src:15"]
    },
    {
      "id": "pain:credit-burn",
      "statement": "I can't tell what a table will cost until the credits are already gone, and the bill keeps climbing as we scale.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "Credits disappear faster than expected, and each action costs a different amount.",
        "operational": "Teams cannot forecast monthly spend, so they ration enrichment, restructure tables to save credits, or move steps to other tools and scripts.",
        "personal": "The builder has to defend a bill they could not predict and second-guess every column they add."
      },
      "workflow": "Building a Clay table: adding waterfall, Claygent and HTTP API columns, running them on the full list, then checking the usage tab after the credits have already been charged.",
      "type": "felt",
      "confidence": "high",
      "priority": 2,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Recurring 2026 complaints on Trustpilot and review sites about credits vanishing, plus users on Clay's own pricing thread asking to stay on legacy plans after the March 2026 change.",
        "cites": ["src:2", "src:4", "src:5"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Clay's March 2026 move to Data Credits plus Actions, which made HTTP API steps a metered cost.", "cites": ["src:5", "src:6"]},
        {"event": "Volume grows past the first test tables.", "cites": ["src:4", "src:23"]}
      ],
      "who_feels": ["technical_evaluator", "economic_buyer"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {"situation": "venting", "verbatim": "Credits also seem to disappear pretty fast and the cost can be a lot for smaller teams.", "cites": ["src:4"]},
            {"situation": "when_it_bites", "verbatim": "HTTP function actually costs more than before. Why is this?", "cites": ["src:5"]},
            {"situation": "when_looking", "verbatim": "For people doing a lot of enrichment in Clay, how do you keep costs predictable as volume grows?", "cites": ["src:23"]}
          ],
          "costs_them": "Time spent restructuring tables to save credits, and second-guessing every validation step.",
          "fears": "Running out mid-month or being blamed for an overage.",
          "dream_outcome": "Knowing the cost of a run before pressing the button."
        },
        "economic_buyer": {
          "says": [
            {"situation": "when_comparing", "verbatim": "Over time though, it's gotten pretty expensive (honestly, quite expensive)", "cites": ["src:4"]},
            {"situation": "when_refusing", "verbatim": "Complex and overpriced.", "cites": ["src:2"]}
          ],
          "costs_them": "Spend that grows faster than pipeline, which turns renewal into a fight.",
          "fears": "Paying for activity rather than outcomes.",
          "dream_outcome": "Spend that tracks results and can be budgeted a quarter ahead."
        }
      },
      "relief": {
        "line": "A bill you saw coming. The cost of a run is known before it runs, and the month closes without surprises.",
        "says": [],
        "gap": "No buyer voice found describing predictable spend. Clay's own claim that 90% of customers never hit an Actions limit is seller voice."
      },
      "euphoria": {
        "line": "Spend tied to pipeline. Enrichment budget is set once a year and defended with booked meetings, not credit counts.",
        "says": [],
        "gap": "Not found in review sites or community threads swept."
      },
      "segments": ["seg:lean", "seg:agency", "seg:revops"],
      "feature_ref": "feat:waterfall",
      "cites": ["src:2", "src:4", "src:5", "src:6", "src:8", "src:23"]
    },
    {
      "id": "pain:crm-duplicates-hygiene",
      "statement": "Every enrichment push leaves duplicates and stale records in the CRM, and someone has to clean it up before reps will trust it.",
      "element": "b2b:ease_of_doing_business:organization",
      "shape": {
        "surface": "Duplicates, stale contacts and half-filled properties pile up in HubSpot or Salesforce.",
        "operational": "RevOps spends cycles on dedupe and validation guardrails instead of new pipeline programs, and pipeline reporting is off.",
        "personal": null,
        "personal_note": "Job posts show companies paying for the cleanup. No source in the sweep has a RevOps person describing what it costs them personally."
      },
      "workflow": "Clay write-back to HubSpot or Salesforce through create-or-update actions, then dedupe, validation and lifecycle-stage audits in the CRM.",
      "type": "felt",
      "confidence": "medium",
      "priority": 3,
      "felt_evidence": {
        "kind": "hiring",
        "what": "Job posts for GTM engineers name CRM data hygiene, dedupe and validation guardrails across Clay and connected systems as core duties.",
        "cites": ["src:14", "src:13", "src:12"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Enriched Clay data starts flowing into the CRM at volume.", "cites": ["src:12"]},
        {"event": "Leadership pushes AI initiatives on top of CRM data that is not ready for them.", "cites": ["src:15"]}
      ],
      "who_feels": ["champion", "technical_evaluator"],
      "by_role": {
        "champion": {
          "says": [
            {"situation": "when_looking", "verbatim": "Implement guardrails for data quality (validation, dedupe, error handling) across Clay and connected systems.", "cites": ["src:14"]},
            {"situation": "to_their_boss", "verbatim": "Ensure CRM data hygiene and pipeline accuracy", "cites": ["src:13"]}
          ],
          "costs_them": "Headcount spent on cleanup, and pipeline reports nobody fully trusts.",
          "fears": "Reps stop logging activity because the CRM looks unreliable.",
          "dream_outcome": "A CRM of record that stays clean while enrichment runs at volume."
        },
        "technical_evaluator": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "Ensure enriched Clay data flows into CRM pipelines without hygiene issues or data loss.", "cites": ["src:12"]}
          ],
          "costs_them": "Building and maintaining matching logic for every write-back.",
          "fears": "One bad sync overwriting good CRM fields for every user.",
          "dream_outcome": "Write-backs that only fill gaps and never create a duplicate."
        }
      },
      "relief": {
        "line": "Clean sync. Enrichment lands in the CRM without new duplicates or overwritten fields.",
        "says": [],
        "gap": "Only job-post and vendor language found. No RevOps buyer quoted on the after state."
      },
      "euphoria": {
        "line": "The CRM is the truth. Reps work from it and leadership reports off it without a cleanup sprint first.",
        "says": [],
        "gap": "Not found in sources swept."
      },
      "segments": ["seg:revops", "seg:lean"],
      "feature_ref": "feat:audiences",
      "cites": ["src:12", "src:13", "src:14", "src:15"]
    },
    {
      "id": "pain:tables-break",
      "statement": "My tables break or misfire in ways I can't predict, and every bug quietly burns money until I catch it.",
      "element": "b2b:ease_of_doing_business:stability",
      "shape": {
        "surface": "Workflows fail silently, Claygent and builder bugs, unpredictable runs.",
        "operational": "Someone has to babysit tables, rerun rows and file support tickets. Spend leaks while it is broken.",
        "personal": "The builder owns a system they cannot fully trust and gets blamed when it misfires."
      },
      "workflow": "Running multi-step Clay tables (waterfall, Claygent, HTTP, CRM write-back) on thousands of rows, then checking failed rows and support.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Dated Trustpilot reviews from January and February 2026 report bugs that cost money daily, and job posts pay for someone to keep tables running without manual intervention.",
        "cites": ["src:3", "src:12"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Moving a table from a test batch to thousands of records.", "cites": ["src:12"]},
        {"event": "An AI column or builder starts returning bad output after a platform change.", "cites": ["src:20"]}
      ],
      "who_feels": ["technical_evaluator", "end_user"],
      "by_role": {
        "technical_evaluator": {
          "says": [
            {"situation": "venting", "verbatim": "This particular bug hasnt been fixed and is costin me money every single day.", "cites": ["src:3"]},
            {"situation": "venting", "verbatim": "Bugs and the flows you can't predict and understand which lead to more and more spendings.", "cites": ["src:3"]},
            {"situation": "when_it_bites", "verbatim": "anyone having heavy trouble w claygent builder bugging out?", "cites": ["src:20"]}
          ],
          "costs_them": "Rerun time, wasted credits and support back-and-forth.",
          "fears": "A broken table running overnight on the whole list.",
          "dream_outcome": "Tables that run on thousands of rows without being watched."
        },
        "end_user": {
          "says": [
            {"situation": "when_refusing", "verbatim": "One of the absolute worst support experiences I have ever had.", "cites": ["src:2"]}
          ],
          "costs_them": "Campaigns that wait on a fix.",
          "fears": "No one to call when it breaks.",
          "dream_outcome": "Problems solved by support in hours, not left to the user."
        }
      },
      "relief": {
        "line": "Runs you can leave alone. The table finishes on the full list with no surprise failures.",
        "says": [],
        "gap": "No buyer voice describing stable runs found in reviews or community pages."
      },
      "euphoria": {
        "line": "Infrastructure, not a project. Workflows built a year ago still run, and the team builds new ones instead of fixing old ones.",
        "says": [],
        "gap": "Not found in sources swept."
      },
      "segments": ["seg:lean", "seg:agency", "seg:revops"],
      "feature_ref": "feat:workflows",
      "cites": ["src:2", "src:3", "src:11", "src:12", "src:20"]
    },
    {
      "id": "pain:steep-learning-curve",
      "statement": "It takes months to get good at it, and until then I'm watching tutorials and still can't build a table that does anything useful.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Formulas, conditional runs and column dependencies feel like engineering, not a spreadsheet.",
        "operational": "Seats sit unused or half-built, and value lands only once someone skilled builds the workflows.",
        "personal": "The person who pushed for the tool feels stuck and starts to doubt themselves."
      },
      "workflow": "First weeks in Clay: Clay University videos and templates, then building waterfall and formula columns from scratch.",
      "type": "felt",
      "confidence": "high",
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Learning-curve complaints recur across reviews from June to September 2026 and in a March 2026 community thread.",
        "cites": ["src:2", "src:4", "src:10"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "A new seat is bought, or a rep or founder is told to build outbound in Clay themselves.", "cites": ["src:10"]}
      ],
      "who_feels": ["end_user", "technical_evaluator"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "I’ve experienced lots of frustration. I think I’m doing something wrong.", "cites": ["src:10"]},
            {"situation": "when_refusing", "verbatim": "Extremely difficult to use, not intuitive at all.", "cites": ["src:2"]}
          ],
          "costs_them": "Weeks before the first useful campaign.",
          "fears": "Looking incapable with a tool everyone else claims to master.",
          "dream_outcome": "A working campaign in the first week without learning the tool's internals."
        },
        "technical_evaluator": {
          "says": [
            {"situation": "when_comparing", "verbatim": "The learning curve is steeper than the marketing makes it seem.", "cites": ["src:4"]}
          ],
          "costs_them": "Ramp time that has to be justified to the buyer.",
          "fears": "Buying a platform the team never adopts.",
          "dream_outcome": "Teammates who can build without them."
        }
      },
      "relief": {
        "line": "It clicks. The basics are figured out and the tool starts paying back the time spent.",
        "says": [
          {"role": "end_user", "verbatim": "steep learning curve, but once you've figured out the basics, it's insanely powerful what this tool can do", "cites": ["src:2"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "A career skill. Mastering the tool turns into a superpower and a job title.",
        "says": [
          {"role": "technical_evaluator", "verbatim": "Clay is my superpower of choice when it comes to GTM orchestration, visibility & business intelligence.", "cites": ["src:2"]}
        ],
        "gap": null
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": null,
      "feature_note": "No listed feature removes the ramp. Done-for-you templates, an agent that builds tables from a goal, or a managed service would.",
      "cites": ["src:2", "src:4", "src:10"]
    },
    {
      "id": "pain:agency-unpredictable-margins",
      "statement": "Since every step costs an action, I can't quote a client a fixed price without guessing at my own margin.",
      "element": "b2b:table_stakes:acceptable_price",
      "shape": {
        "surface": "Metered Actions and data credits make the cost per client hard to estimate.",
        "operational": "Agencies have to model usage per client, split plan costs across clients, and reprice retainers. Heavy API workflows that used to be free now cost money.",
        "personal": "The agency owner carries the margin risk on every retainer."
      },
      "workflow": "Agency running Clay workspaces for several clients with BYO API keys over HTTP, then pricing a monthly retainer per client.",
      "type": "felt",
      "confidence": "medium",
      "priority": 6,
      "felt_evidence": {
        "kind": "complaining",
        "what": "On Clay's March 2026 pricing announcement, users asked whether they could stay on legacy plans and worked out that heavy API users are better off there.",
        "cites": ["src:5"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Clay's March 2026 pricing change made HTTP API calls a paid Action and removed the cheaper API tier.", "cites": ["src:5", "src:9"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "when_comparing", "verbatim": "if we use a ton of API and HTTPS calls, we're better off on legacy", "cites": ["src:5"]},
            {"situation": "when_refusing", "verbatim": "Clay became worse for small GTM shops, but better for enterprises", "cites": ["src:8"]}
          ],
          "costs_them": "Thinner, less predictable margin per client.",
          "fears": "A client's heavy month wiping out the retainer's profit.",
          "dream_outcome": "Knowing the data cost per client up front and pricing on it."
        }
      },
      "relief": {
        "line": "Priced with confidence. Each client's data cost is a known line item.",
        "says": [],
        "gap": "Agency voices found only through a vendor article and the Clay pricing thread. No agency owner describing the after state."
      },
      "euphoria": {
        "line": "Margin that scales. Adding a client adds profit, not risk.",
        "says": [
          {"role": "economic_buyer", "verbatim": "I'm able to GTM at scale across multiple accounts", "cites": ["src:2"]}
        ],
        "gap": null
      },
      "segments": ["seg:agency"],
      "feature_ref": null,
      "feature_note": "This is a pricing-model pain, not a feature gap. Per-client cost visibility or a cost estimate before each run would ease it.",
      "cites": ["src:5", "src:8", "src:9", "src:22"]
    },
    {
      "id": "pain:agency-builder-capacity",
