        "personal": null,
        "personal_note": "Only hiring posts were found. No agency owner described the personal toll in sources that could be fetched."
      },
      "workflow": "Agency owner hiring a part-time or full-time GTM engineer through the Clay community jobs board, screening by Loom walkthroughs of Clay tables.",
      "type": "felt",
      "confidence": "medium",
      "priority": 7,
      "felt_evidence": {
        "kind": "hiring",
        "what": "A July 2026 Clay community post hires a long-term GTM engineer to manage multiple client accounts and requires 6+ months building real Clay tables. GTM engineer postings rose 205% in 2025.",
        "cites": ["src:21", "src:16"]
      },
      "revealed_by": null,
      "triggers": [
        {"event": "Signing more clients than current builders can handle.", "cites": ["src:21"]}
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "when_looking", "verbatim": "This is not a quick gig, we want someone who sticks around and gets better over time.", "cites": ["src:21"]}
          ],
          "costs_them": "Growth capped by headcount, plus ramp cost for every new builder.",
          "fears": "A key builder leaving with the client workflows in their head.",
          "dream_outcome": "Client delivery that does not depend on one scarce person."
        }
      },
      "relief": {
        "line": "Delivery without heroes. A new client goes live without hiring another specialist.",
