        "gap": "Not found. Agency owner voices on LinkedIn and Reddit could not be fetched directly."
      },
      "euphoria": {
        "line": "An agency that scales. Client count grows faster than headcount.",
        "says": [],
        "gap": "Not found in sources swept."
      },
      "segments": ["seg:agency"],
      "feature_ref": "feat:claygents",
      "cites": ["src:16", "src:21"]
    },
    {
      "id": "pain:ai-research-unreliable",
      "statement": "The AI research column looks great on five rows, then on the full list half the answers are off and I have to check them anyway.",
      "element": "b2b:ease_of_doing_business:component_quality",
      "shape": {
        "surface": "Claygent and AI columns return wrong, irrelevant or hit-or-miss output.",
        "operational": "Rows need human spot checks, personalization built on bad research misfires, and credits are spent on reruns.",
        "personal": "The builder cannot vouch for what goes out under a rep's name."
      },
      "workflow": "Claygent or AI columns researching each account (website, news, hiring), feeding a first-line or qualification column before export to the sequencer.",
