    {
      "id": "pain:personalization-sameness",
      "statement": "Everyone is scraping the same LinkedIn data into the same AI opener, so my 'personalized' email is the tenth one the prospect got this week.",
      "element": "b2b:functional:improved_top_line",
      "shape": {
        "surface": "AI-written first lines that read like everyone else's.",
        "operational": "Reply rates slide, and agencies see clients judge them on a trend line they cannot explain.",
